function decode(link){if(!link.startsWith("saavn://"))throw new Error("Invalid Saavn link");return JSON.parse(decodeURIComponent(link.slice(8)))}function q(v){const m=String(v||"").match(/\d+/);return m?Number(m[0]):0}exports.getStream=async({link})=>{const s=decode(link),u=Array.isArray(s?.downloadUrl)?s.downloadUrl:[],m=new Map;for(const x of u)if(x?.url)m.set(x.url,x);const r=[...m.values()].sort((a,b)=>q(b.quality)-q(a.quality)).map(x=>({server:`Saavn ${x.quality||"Audio"}`,link:x.url,type:"mp4",quality:x.quality||"audio",tag:"Audio"}));if(!r.length)throw new Error("No Saavn audio stream was returned");return r};